  "partsGuide.laserT": "⚔️ Laser",
  "partsGuide.laserD": "<span style=\"color:var(--red)\">ATT</span> (attack power) +5–320. <b>Fires automatically every turn</b>, stripping the enemy shield first, then dealing direct HP damage. 100% accuracy, unlimited range. Some mythic lasers (MW01·RB10) absorb part of the damage dealt as your own HP/shield.",
  "partsGuide.missileT": "🚀 Missile",
  "partsGuide.missileD": "<span style=\"color:#ff8844\">ATT</span> (attack power) + <b>shield-piercing</b> damage. Passes through shields to hit HP directly — effective against shield-heavy ships (Chiks/Aureus flagships). One shot per turn, 100% accuracy. Mythic grade (MMB01 Lee Hwi-so Missile) adds bonus Void damage.",
  "partsGuide.shieldT": "🛡️ Shield",
  "partsGuide.shieldD": "<span style=\"color:var(--blue)\">INT</span> (shield strength) + <b>maxSH</b> (max shield). Auto-regenerates shields by (INT × 1.5%) each turn. Missiles pass through, but lasers are absorbed first. Mythic grade (MS01) revives once when destroyed.",
  "partsGuide.armorT": "🛡 Armor",
  "partsGuide.armorD": "<b>maxHP</b> (max health) + <span style=\"color:var(--gold)\">DEF</span> (defense). DEF flattens incoming damage. Some armor (RB series) has <b>repairRate</b> → auto-repairs a % of HP each turn. Mythic grade (MA01·RB10) revives on destruction or grants lifesteal.",
  "partsGuide.engineT": "⚡ Engine",
  "partsGuide.engineD": "<span style=\"color:var(--cyan)\">TEC</span> (tech) — <b>increases attack speed in combat</b>: <span style=\"color:#cce\">fires first each turn + first-strike ATT +20% + higher evasion</span>",
  "partsGuide.engineMove": "<b style=\"color:#fff\">Planet Travel Range — 3 Tiers</b>:<br><span style=\"color:var(--cyan)\">Tier 1</span> Standard engines (E01–E12) — move <b>1 adjacent hop</b> (base)<br><span style=\"color:var(--gold)\">Tier 2</span> Legendary engines (E15·ME01·SE01 — even just one in the fleet) — <b>2-hop</b> move<br><span style=\"color:var(--purple)\">Tier 3</span> Blink engines (warp on all ships) — <b>unlimited jump</b> (ignores black holes/rings + fleet speed +20%)",
