  "credits.closeArrow": "Close →",
  "prologue.l1": "Quantum transmission received... Commander {nm} mental sync 99.8%...",
  "prologue.l2": "Oh, you’re awake? Waited a century, and now that you’re up it feels anticlimactic.",
  "prologue.l3": "Who am I? Baekgu. AI Jindo. Been picking up scrap and running a cover company for a century.",
  "prologue.l4": "Supreme Commander {nm} of {co}! Your job is simple: earn through trade, real estate, and combat, then smash Ursa Major who blockades Earth.",
  "prologue.l5": "I scraped together this much from junk — so {nm}, hop on ship {ship}, conscript the legendary heroes, and let’s go save Earth!",
  "prologue.l6": "P01 Proxima B — Commander {nm} awakening. Connecting to {co} hub...",
  "prologue.systemLabel": "⚡ System",
  "quest.npc.admiral": "Admiral",
  "quest.npc.broker": "Broker",
  "quest.combat.title1": "Sweep the Pirate Fleet",
  "quest.combat.title2": "Repel the Chiks Scouts",
  "quest.combat.title3": "Intercept the Smuggler",
  "quest.combat.title4": "Support Lane Patrol",
  "quest.combat.desc1": "Admiral Rohan: A pirate gang has nested in this lane. Our merchants are robbed daily. Use your fleet to sweep them. The reward will be generous.",
  "quest.combat.desc2": "Admiral Rohan: A few Chiks scouts crossed into our airspace. Drive them off and report the wreckage — reward is guaranteed. Don’t overextend.",
  "quest.combat.desc3": "Admiral Rohan: Classified intel. A smuggler will pass this lane soon. Intercept and seize the cargo — your share will be generous.",
  "quest.combat.desc4": "Admiral Rohan: Our patrol is shorthanded. Run a lap with us and standard pay is yours. Easy work.",
  "quest.delivery.title1": "Urgent Cargo Delivery",
  "quest.delivery.title2": "Classified Document Drop",
  "quest.delivery.title3": "Medicine Transport",
  "quest.delivery.title4": "Parts Procurement",
  "quest.delivery.desc1": "Carrier Maki: No time to lose. Just take this cargo to the adjacent planet — generous freight pay if it’s fast.",
  "quest.delivery.desc2": "Broker Cloud: Diplomatic channels are sealed. You can move the document unseen. Tell no one — hand it to the contact in person.",
  "quest.delivery.desc3": "Merchant Kane: Can you deliver my medicine to the next planet? Reward guaranteed. Watch for pirates on the way.",
  "quest.delivery.desc4": "Foreman Matthias: My line is down. Fetch the parts from the next planet and I’ll pay cash on the spot.",
  "quest.gather.title1": "Mine Rare Minerals",
  "quest.gather.title2": "Collect Radiation Data",
  "quest.gather.title3": "Wreckage Search",
  "quest.gather.title4": "Recover Supplies",
  "quest.gather.desc1": "Trader Rafael: Word is rare minerals appeared in the nearby belt. Mine for ~2 turns and I’ll pay market rate. Don’t get greedy.",
  "quest.gather.desc2": "Researcher Helen: I need stellar-wind radiation data. Run the sensors for ~2 turns and I’ll pay cleanly. Retreat at once if pirates show up.",
  "quest.gather.desc3": "Scrapper Logan: Looking for someone to hit the battle wreckage zone. Split whatever you bring back in ~2 turns. Just come back alive.",
  "quest.gather.desc4": "Militia Captain Hawk: Our supplies remain in the Chiks wreckage. Recover them and you get a reward. About 2 turns — watch for scouts.",
  "quest.explore.title1": "Lane Survey Mission",
  "quest.explore.title2": "Stellar Survey Support",
  "quest.explore.title3": "Unknown Sector Probe",
  "quest.explore.title4": "Satellite Orbit Survey",
  "quest.explore.desc1": "Admiral Rohan: Scout the new lane candidates yourself. Hit the left [Wreckage Scan] button to deploy your fleet. Report what you find.",
  "quest.explore.desc2": "Navigator Claire: This system’s coordinates are uncalibrated. A couple of [Wreckage Scan] runs will do it. Bonus: a copy of the nav data.",
  "quest.explore.desc3": "Admiral Rohan: A sector has empty records. Go and fill the data. Pull back if it gets risky — your safe return comes first.",
  "quest.explore.desc4": "Controller Sio: Reports say some satellite orbits are wobbling. Run a lap and find the issue. Detailed survey fee is extra.",
  "quest.buy.title1": "Specialty Buy Order",
  "quest.buy.title2": "Rarity Collection",
  "quest.buy.title3": "Bulk Order",
  "quest.buy.title4": "Trade Support",
  "quest.buy.desc1": "Magnate Lee: Bring N specialty units and I’ll buy them at 2× market. Doesn’t matter where you source them.",
  "quest.buy.desc2": "Collector Yamada: Gather N rare specialties. I’ll pay 2× and leave no transaction record.",
  "quest.buy.desc3": "Wholesaler Erma: Deliver N units to our exchange and we’ll pay 2× market. Please be quick.",
  "quest.buy.desc4": "Broker Cloud: The client is in a hurry. Grab N specialty units now — reward is 2× market.",
