  "ui.noHoldExpHelp": "Buy at Ship Trade → ⚙️ Buy Parts → \"Special Hold Expansion\", or craft at the Workshop.",
  "ui.crewMaxN": "Crew max <b style=\"color:var(--green)\">{n}</b>",
  "ui.slotSwapHint": "💡 Click a slot to <b>move/swap</b> ships between slots. You can pick a ship card first.",
  "ui.cargoBayReachedMax": "<b style=\"color:var(--cyan)\">{nm}</b> cargo bay<br>reached the cap of <b style=\"color:var(--gold)\">100</b> slots.",
  "ui.swapRecruitConfirm": "Dismiss <b style=\"color:var(--red)\">{old}</b> and recruit <b style=\"color:var(--cyan)\">{new}</b>.",
  "ui.swapLegendConfirm": "Dismiss <b style=\"color:var(--red)\">{old}</b> and recruit <b style=\"color:var(--gold)\">{new}</b>?",
  "ui.civUnknown": "??? Civilization",
  "ui.miniGameControls": "<b style=\"color:#66ddff\">Arrow/WASD</b> or <b style=\"color:#66ddff\">{mouse}</b> · <b style=\"color:#ffcc66\">RShift/click</b> laser · <b style=\"color:#ff99cc\">Ctrl/Enter</b> missile · <b style=\"color:#ff44ff\">LShift</b> ultimate (lightning, 10s)",
  "ui.youWereDifferent": "... But you were different.",
  "ui.endingFleetText": "The fleet of <b style=\"color:var(--gold)\">{nm}</b>, Supreme Commander of {co},<br>defeated the galactic blockader <b style=\"color:#ff3366\">Ursa Major</b>.",
  "ui.chixShadowProse": "A purple shadow flickered on the frontier planet. <b style=\"color:#cc66ff\">Chiks</b> scouts. At first we thought them mere invaders, and we grew the fleet one ship and one person at a time. Traders joined, engineers gathered, and the Commander’s hands trembled no more.",
  "ui.unknownAppearedCode": "They say <span style=\"color:var(--purple);font-weight:bold\">{thing}</span> appeared. Without any identification code.",
  "ui.noStatInfo": "<div style=\"font-size:12px;color:var(--dim)\">No info</div>",
  "ui.commanderPowerLine": "Commander Power <span style=\"color:var(--cyan)\">{plv}</span> · Boost ×{mult}",
  "ui.endingFlagshipProse": "{ship} sets sail. The 8 heroes' sync rate is 99.7% — the same number that woke the Commander a century ago. In its final moment, Ursa Major said: <i style=\"color:#ddd\">\"There is a greater threat than me.\"</i> At the midnight the boss's shell collapsed, Earth's blockade lifted with it.",
  "ui.dataLookupVia": "Data lookup is available after Google login as <span style=\"color:var(--cyan)\">{email}</span>.",
  "ui.blackfalconNickname": "Locals call them <span style=\"color:#ff66ff;font-weight:bold\">Blackfalcon</span>{call}",
