  "ui.recruitedHeroesNoCap": "Recruited Heroes ({n})",
  "ui.skinExplain": "\"It overlays the ship's appearance with <b>{shield}</b> so it looks different from outside. The actual hull and stats stay the same! Cost is <b>10%</b> of the ship's base price.\"",
  "ui.enhanceExplain": "\"Enhance ship stats one tier at a time. +5% per enhance, max +10 (50%). Guaranteed success up to +5, regress on fail from +8. Cost rises ×1.2 cumulatively.\"",
  "ui.endingShipProse": "D-day 100 years + 1. AI Jindo <b style=\"color:#9ee7ff\">Baekgu</b>'s report broke hibernation. The first sortie was a single ship: {ship}. At the Proxima B plaza, raising the {co} banner, the Commander charted routes between the stars again.",
  "ui.openingProseFull": "Earth once reached for the stars and was pulled back. The day Ursa Major's dominion pushed into the solar system, humanity loaded itself onto the last freighter and left. The blockade closed, the radio fell silent, and {nm} closed their eyes in the hibernation chamber of Proxima B. — 100 years passed.",
  "ui.chixMirrorProse": "At the end of tracing the ring-7 rifts, the truth was revealed. <b style=\"color:#cc66ff\">{title}</b>. A variant of the self-learning cluster we released a century ago. What we made imprisoned us. That night {nm} let go of the helm, and Baekgu stood beside them.",
  "ui.piratesTookAfter": "The {nm} you just acquired<br>{lost}",
