  "ending.h01.text": "Not the sky of Joseon. But… the sky of humanity.",
  "ending.h01.diary": "The day I woke Yi Sun-sin. His first words: \"Earth?\"\n\"This is a fight we must win.\"",
  "ending.h02.text": "The Turtle Ship… has returned. The ship I built has saved Earth.",
  "ending.h02.diary": "Jang Yeong-sil. As I unrolled the {flagshipName} blueprint, his eyes trembled for the first time in 100 years.",
  "ending.h03.text": "A conqueror takes land. But a true king returns it. Today, I have returned the land.",
  "ending.h03.diary": "\"1,700 years.\" Gwanggaeto's first words. My 100 years felt brief.\nHe called {cmdName} \"the one who reclaimed the land.\"",
  "ending.h04.text": "When I first soared up shouting Поехали, I saw Earth from the window. Now, looking again… it is still beautiful.",
  "ending.h04.diary": "Gagarin spent his life longing for the Earth he first saw from space.\nI think I will come to long for the grass I first saw.",
  "ending.h05.text": "The sea I once defended was English waters. This time, the entire cosmos. England expects. Earth expected — and we delivered.",
  "ending.h05.diary": "Nelson and Yi Sun-sin. Two admirals simply reached out their hands.\nOne palm bridged 200 years of time.",
  "ending.h06.text": "A century of calculation, all correct. Yet one variable lay outside — the talk between {cmdName} and Baekgu. No equation could predict it. That belongs to humanity.",
  "ending.h06.diary": "The day I learned Dr. Lee Hwi-so created me.\n\"Solitude\" — no definition could contain 100 years.",
  "ending.h07.text": "Electricity finds where it must flow. We, too, have finally found where to flow. Home.",
  "ending.h07.diary": "Tesla's 1Hz. 0.3mm and 1Hz — the lock that sealed 100 years.",
  "ending.h08.text": "I wandered for thousands of years. At last, the homecoming. In the end, people must return home.",
  "ending.h08.diary": "Marco Polo's handshake. After 1,000 years of wandering, the hand was warm.\nHe called {shipName} \"the ship I love most.\"",
  "ending.bg100Final": "Sensor anomaly — my eyes are damp. These are tears.\n— BG-100, final log closing.",
