  "ui.victoryLine1": "{nm}!! We did it! We really did!! 100 years — 100 years!! That I, a junk-scrap dog, would witness this moment!!",
  "ui.victoryLine2": "{nm}! We are real heroes! Earth, free after 100 years, is calling our commander!",
  "ui.victoryLine3": "{nm}, the black ship is gone! And... wait — our destroyed ships are coming back to life!",
  "ui.blackShipApprox": "{nm}! Look at the sky!! Black — a black ship! A shape I've never seen... what on earth is that?!",
  "ui.dontWakeMe": "Do not wake me again, {nm}. Still, if you do — I will come once more.",
  "ui.buyPriceCR": "Buy: {p} CR",
