  "ui.voidGovernorReact": "Wait... wait!! Do they know we took the Void Governorship?! What... what is that being?!",
  "chatbot.unclearAsk": "Good question, but it's vague to me too. Try keywords like \"craft\", \"crew\", \"ship\", \"hero\".",
  "chatbot.tradeTip": "Each planet has unique faction specialties. Premium goods require power/fame thresholds. Buy low, sell high on other planets. Expand cargo to carry more in one trip.",
  "chatbot.matPlanetHeader": "🔧 Crafting materials & specialty goods come by faction. Visit a faction's worlds and they always sell its signature material:",
