  "ship.capturedLabel": "{tier}-class Captured Ship",
  "quest.crew.QL01.nm": "Gabriel de Clifford",
  "quest.crew.QL01.desc": "Space mage. Shield regen +30%.",
  "quest.crew.QL02.nm": "Oceanus Carter",
  "quest.crew.QL02.desc": "Legendary space pilot. Evasion +25%.",
  "quest.crew.QL03.nm": "Seira Ark",
  "quest.crew.QL03.desc": "Galactic sniper. First-strike chance +40%.",
  "quest.crew.QL04.nm": "Caesar Volte",
