  "cargo.CH01.nm": "Earth Resistance Military Container",
  "cargo.CH01.desc": "Standard military container used by the Earth Resistance for supply ops. Graffiti inside reads \"Humanity's last hope is stored here.\"",
  "cargo.CH02.nm": "Mechanica Modular Cargo Bay Mk.I",
  "cargo.CH02.desc": "Standard-spec modular cargo bay of the Mechanica Republic. Built with vibration absorption to safely transport precision machine assemblies.",
  "cargo.CH03.nm": "Krieg Combat Supply Crate",
  "cargo.CH03.desc": "Military supply crate used by Krieg combatants on expeditions. Interior designed to cram in anything from explosives to rations.",
  "cargo.CH04.nm": "Superbia Gravity-Compression Hold",
  "cargo.CH04.desc": "Premium gravity-compression cargo system used by Superbia noble fleets. Rearranges interior space with a gravity field — far more efficient than standard holds.",
  "cargo.CH05.nm": "Chiks Biotic Storage Sac",
  "cargo.CH05.desc": "Organic storage sac cultivated with Chiks bio-engineering. Living cell membranes wrap and protect cargo, reshaping themselves to fit various loads.",
  "cargo.CH06.nm": "Aureus Gold Vault Module",
  "cargo.CH06.desc": "Gold vault module of the Aureus Merchants' Guild. Used by long-haul traders to securely store valuables and credits.",
  "cargo.CH07.nm": "Void Dimensional Pocket",
  "cargo.CH07.desc": "Pocket space crafted by the Void's mysterious dimension-folding tech. Bends physical laws to store massive cargo regardless of external size.",
  "cargo.CH08.nm": "Lee Hwi-soh Quantum Compression Hold",
  "cargo.CH08.desc": "Compression hold designed by Dr. Lee Hwi-soh based on quantum superposition. Stores cargo in a quantum state — theoretically infinite capacity. A legendary rarity.",
  "cargo.CH09.nm": "Gwanggaeto Fleet Unified Cargo Hold ⚡Legend",
  "cargo.CH09.desc": "Legendary unified cargo hold mounted on Gwanggaeto fleet flagships. Boasts overwhelming load capacity — can supply an entire fleet single-handedly.",
  "cargo.CH10.nm": "Hubble Spatial-Distortion Hold ❖Mythic",
  "cargo.CH10.desc": "Ancient alien tech recovered from the Hubble Telescope wreckage. Warps space itself to create virtually infinite storage. Quest reward only.",
