  "part.ML01.nm": "Tau Missile",
  "part.ML01.desc": "[F06 Earth Resistance] Developed by Dr. Lee Silsok. Lightweight heat-seeking missile for guerrilla warfare. Weak against shields / specialized in armor penetration.",
  "part.ML02.nm": "Krieg Shock Round",
  "part.ML02.desc": "[F04 Krieg] Volcanic magma-core explosive warhead. Approved by Warlord Carlos of the origin zone. Armor-destruction specialist.",
  "part.ML03.nm": "Void Pulse Round",
  "part.ML03.desc": "[F07 Void] Antimatter warhead that warps space. Developed by Rashid al-Tariq's lab. Accuracy unaffected by distance.",
  "part.ML04.nm": "Superbia Gravity Missile",
  "part.ML04.desc": "[F01 Superbia] Designed by Sofia Morel. Gravity-focusing warhead. On hit: enemy ENG -20% (1 turn).",
  "part.ML05.nm": "Mechanica Smart Missile",
  "part.ML05.desc": "[F03 Mechanica] AI-autonomous guidance. Developed by Dmitri. Tracks and hits even evading ships.",
  "part.ML06.nm": "Aureus Gold Harpoon ⚡Legend",
  "part.ML06.desc": "[F02 Aureus] Legendary guided harpoon. Commissioned by Pierre. Solar-core energy warhead pierces DEF.",
  "part.ML07.nm": "Chiks Crystal Frag Round ⚡Legend",
  "part.ML07.desc": "[F05 Chiks] Hyper-velocity crystalstone-shard missile. Crafted by Tagigga. 3-tile AoE blast.",
  "part.MMB01.nm": "Lee Hwi-soh Equation Missile ❖Mythic",
  "part.MMB01.desc": "[Mythic] Embodies Dr. Lee Hwi-soh's particle-physics equations. Pierces DEF/SHD + Crit +30%. Beyond lightspeed, multi-angle attack with multiple shockwaves.",
  "part.SMIS01.nm": "Gwanggaeto Beacon Missile ◈Set",
  "part.SMIS01.desc": "[Gwanggaeto Set (2 pcs)] Owning both: ATT +100, DEF +40. Gwanggaeto (Hero H03) effect. Combines beacon-signal radar jamming with autonomous guidance.",
  "part.SARM01.nm": "Gwanggaeto Hull ◈Set",
  "part.SARM01.desc": "[Gwanggaeto Set (2 pcs)] Owning both: ATT +100, DEF +40. Applies Goguryeo ironclad techniques. Auto-evasion +15% when hit.",
  "part.MW01.nm": "Hermetic Cannon ✦Mythic",
  "part.MW01.desc": "Mythic weapon. Multi-attack chance +40%. Not sold in shops.",
  "part.MS01.nm": "Chronos Barrier ✦Mythic",
  "part.MS01.desc": "Mythic shield. Damage reflect 20% + self-restores 15% maxSH per turn. Not sold in shops.",
  "part.MA01.nm": "Adamant Hull ✦Mythic",
  "part.MA01.desc": "Mythic armor. Crit damage -50%. Not sold in shops.",
  "part.ME01.nm": "Tachyon Drive ✦Mythic",
  "part.ME01.desc": "Mythic engine. After move: ATT +50 (1 turn). Not sold in shops.",
  "part.MMV01.nm": "Void Spear ✦Mythic",
  "part.MMV01.desc": "[Mythic ultimate missile] A massive spear condensed from Void-dimensional energy. After charging, instantly destroys one enemy ship unconditionally (30s cooldown). Fully pierces DEF/SHD.",
  "part.SW01.nm": "Geobukseon Cannon ◈Set",
  "part.SW01.desc": "Yi Sun-sin Set (2 pcs). Owning both: combat ATT +80.",
  "part.SA01.nm": "Geobukseon Armor ◈Set",
  "part.SA01.desc": "Yi Sun-sin Set (2 pcs). Owning both: combat ATT +80.",
