  "lock.npcDefault": "Staff",
  "lock.npcDefaultBase": "Cannot serve you yet. Please clear the area to safety.",
  "lock.declineF01": "The noble parlor does not open lightly.",
  "lock.declineF02": "Bring at least one gold bar. Empty-handed isn't allowed.",
  "lock.declineF03": "Log auth failed. Clear the pirate data and re-authenticate.",
  "heroGreet.H01": "Joseon's seas may have set, but seas worth defending remain many. Commander, leave that fight to me.",
  "heroGreet.H02": "Oh, this ship's blueprint... plenty to tune. Leave it to me, Commander?",
  "heroGreet.H03": "All this vast space, unexplored?! Commander, show me the stars to conquer.",
  "heroGreet.H04": "I can go to space again... Poyekhali! Let's go, Commander!",
  "heroGreet.H05": "England expects... no, all humanity expects now. I'll take this fleet.",
  "heroGreet.H06": "Fascinating. A voyage that splits time and space... if my math is right, we will surely win.",
  "heroGreet.H07": "Current finds its path. I shall send my lightning to the enemy.",
  "heroGreet.H08": "So many uncharted routes — and you want to stay still? Commander, let's set sail!",
  "map.help": "[🖱️ L-click→move  R-click→3D rotate  Wheel→zoom  Click planet→select]",
  "map.codexHint": "📖 Exploration Codex — an archive collecting the ships, parts, characters, planets, goods, civilizations, survival knowledge, and voyage log (Baekgu's diary) you discover on your journey. Open it from 'Exploration Codex' in the left menu.",
