  "ursa.fightEnter": "⚔️ Enter Battle!",
  "ursa.intro.sys1": "⚠️ Warp signal detected... Ursa Major fleet appears. 15 elite escorts confirmed.",
  "ursa.intro.ursa1": "... Humanity's small fleet has finally come this far.",
  "ursa.intro.ursa2": "100 years ago, we sealed your star. We thought your silence would last forever.",
  "hof.unnamed": "Anonymous",
  "hof.globalLoading": "🌐 Loading global Hall of Fame... (up to 15s)",
  "feedback.copyBtn": "📋 Copy",
  "feedback.sendBtn": "📧 Send by Email",
