  "backup.commander": "commander",
  "ursa.intro.cmd1": "That blockade ends today. The hundred-year debt — paid right now.",
  "ursa.intro.ursa3": "Bold. But what you saw was our shadow. I'll show you the true form.",
  "ursa.intro.ursa4": "Alpha, Beta, Gamma, Delta, Epsilon escorts — form the battle line!",
  "ursa.intro.bk": "Ten million power! Plus escorts! The real big one — pour every gun on them!",
  "ursa.intro.cmd2": "All hands, form ranks. End it with the first strike. Fire!",
  "ursa.startFinalBattle": "⚔️ Start Final Battle",
  "ursa.later": "Later",
  "ursa.bossName": "Ursa Major",
  "ursa.phase2Line": "Impressive... but it's not over. Now... try to stop this!",
  "falcon.afterUrsa": "Excellent... you broke my whole fleet. The first in a thousand years. Then — I'll face you myself.",
  "ursa.outro.1": "Impossible... a mere human fleet... broke the 100-year seal...?",
  "ursa.outro.2": "...Khh... I admit it... you had something we did not...",
  "ursa.outro.3": "A reason to return home... humanity's strong will... it broke us...",
  "ursa.outro.sys1": "💥 Enemy flagship Ursa Major — core collapse confirmed. Escorts destroyed. Warp signal lost.",
  "ursa.outro.bk": "The Earth blockade lifts! Comms incoming! Families... people... see the stars again!",
  "ursa.outro.sys2": "📡 Earth comms restored. Cheers from all humanity broadcast across the galaxy.",
  "ursa.outro.cmd1": "...It's over. 100 years of silence, 100 years of submission — settled by our own hands today.",
  "ursa.outro.cmd2": "Well done, fleet. Heroes, crew — your names are forever in humanity's history.",
  "ursa.outro.cmd3": "We opened humanity's path. From now on, the stars are our friends — and Earth is free forever.",
  "ursa.outro.sys3": "🌍 Earth blockade fully lifted. Humanity liberation declared. — DESTINATION EARTH completed.",
