  "ui.taxRateLine": "Tax rate: <span style=\"color:var(--gold)\">₡{n}/turn</span>",
  "ui.fissureChipShort": "🌀Fissure",
  "ui.winConquerLoseCr": "Win: conquer planet + loot | Lose: -10% credits",
