  "ui.extremeDangerWarn": "Warning: Extremely Dangerous Battle",
  "credits.act5Header": "— ACT 5 · FINAL —",
  "credits.journeyHeader": "— THE JOURNEY SO FAR —",
  "credits.act1Body": "A hundred years of blockade. Ursa Major's black armada ringed the Earth, and humanity was caged in the cold orbit of Proxima B. The front-company {co} scavenged the wrecks and cast-off parts of dead ships to forge a small fleet. Then Baekgu, an AI roused from a long sleep, shook {cmd} awake — and on the day the Mustang's worn engines first lit, everyone held their breath.",
  "credits.act2Body": "A galaxy tangled with seven factions — proud Superbia, golden Aureus, steel Mechanica, war-born Krieg, shadowed Cheeks, the Earth Resistance, and the silent Void. Across 24 worlds {cmd} filled the coffers through trade and tempered the fleet through battle. {n} legendary heroes from across the ages gathered beneath that banner — each carrying their own story, their own vengeance.",
  "credits.act3Body": "Beyond the fissure. From the Void planets came a signal a thousand years old. In the silence between the stars, something was waking. {cmd} gathered Void Crystals, restored the forgotten mythic blueprints, and prepared for the final battle. Baekgu had stopped making jokes.",
  "credits.act4Body": "Earth Liberation. At last, the core of Ursa Major is broken. A century of blockade ends, and the blue planet reclaims its light. Humanity reopens its ruined harbors and sails out again — never to be caged twice.",
  "credits.act5Body": "The Void Abyss. The last duel against Black Falcon, who broke a thousand years of silence. Having overcome an enemy that mirrored their very self, {cmd} stands before the black hole at the heart of the galaxy. Into that place from which no one returns, the commander walks alone.",
  "credits.voidQuote": "\"No one walks out of here alive.<br>Do as you wish.\"",
  "ending.prologueHead": "— PROLOGUE · THE CENTURY OF BLOCKADE —",
  "ending.act1Head": "— ACT I · AWAKENING —",
  "ending.act2Head": "— ACT II · FIRES OF THE FRONTIER —",
  "ending.act3Head": "— ACT III · SLEEPING HEROES —",
  "ending.act4Head": "— ACT IV · THE TRUTH OF THE CHEEKS —",
  "ending.act5Head": "— ACT V · EARTH LIBERATION —",
  "ending.act6Head": "— ACT VI · THE VOID ABYSS —",
  "ending.act6Body": "Ursa's final word was a coordinate. There, where starlight could not reach, lay a black fissure with a single line waiting: — <i style=\"color:#fff\">\"No one walks out of here alive. Do as you wish.\"</i> We went. Knowing — and yet we went. That is the human way. And we — returned.",
  "ending.epilogueHead": "— EPILOGUE · HOMECOMING —",
  "ending.epilogueBody": "D-Day, 100 years + 412 days. {ship} settled onto Earth's grass. Colors no fluorescent lamp had matched in a century filled the commander's eyes; an unfamiliar liquid flowed across Baekgu's sensors. — Humanity reaches for the stars once more. This time, we will not pull the hand back.",
